import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicIntegerArray;
import java.util.function.BooleanSupplier;

public class Harness {
    /** Every wait in this harness is bounded by this; the watchdog is the last resort. */
    private static final long DEADLINE_MS = 5_000L;

    public static void main(String[] args) {
        Atrophy.plan(4);
        Atrophy.watchdog(30000);
        try {
            fifoOrder();
            blockedPutResumes();
            noLossNoDuplication();
            Atrophy.check("harness completed every check without crashing", true);
        } catch (Throwable t) {
            Atrophy.check("harness crashed: " + t, false);
        } finally {
            Atrophy.report();
        }
    }

    private static Thread daemon(String name, Runnable body) {
        Thread t = new Thread(body, name);
        t.setDaemon(true);
        t.start();
        return t;
    }

    /**
     * Bounded wait for a thread to park inside a blocking call. Returns false the moment
     * `escaped` trips (the call returned instead of blocking) or the thread dies.
     * A latch cannot express "is blocked", so this polls thread state with a deadline.
     */
    private static boolean awaitParked(Thread t, BooleanSupplier escaped) {
        long end = System.nanoTime() + DEADLINE_MS * 1_000_000L;
        while (System.nanoTime() < end) {
            if (escaped.getAsBoolean()) return false;
            Thread.State s = t.getState();
            if (s == Thread.State.TERMINATED) return false;
            if (s == Thread.State.WAITING || s == Thread.State.TIMED_WAITING || s == Thread.State.BLOCKED) {
                return !escaped.getAsBoolean();
            }
            try {
                Thread.sleep(1);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
        }
        return false;
    }

    /** Check 1: 200 items through a capacity-2 queue come out in the order they went in. */
    private static void fifoOrder() throws InterruptedException {
        final int N = 200;
        Solution q = new Solution(2);
        int[] taken = new int[N];
        AtomicInteger takenCount = new AtomicInteger();
        AtomicInteger crashes = new AtomicInteger();
        CountDownLatch finished = new CountDownLatch(2);

        daemon("producer", () -> {
            try {
                for (int i = 1; i <= N; i++) q.put(i);
            } catch (Throwable t) {
                crashes.incrementAndGet();
            } finally {
                finished.countDown();
            }
        });
        daemon("consumer", () -> {
            try {
                for (int i = 0; i < N; i++) {
                    taken[i] = q.take();
                    takenCount.incrementAndGet();
                }
            } catch (Throwable t) {
                crashes.incrementAndGet();
            } finally {
                finished.countDown();
            }
        });

        boolean drained = finished.await(10, TimeUnit.SECONDS);
        boolean inOrder = drained && crashes.get() == 0 && takenCount.get() == N;
        if (inOrder) {
            for (int i = 0; i < N; i++) {
                if (taken[i] != i + 1) {
                    inOrder = false;
                    break;
                }
            }
        }
        Atrophy.check("items come out in the order they went in (fifo)", inOrder);
    }

    /** Check 2: put on a full queue blocks, and completes once a take frees a slot. */
    private static void blockedPutResumes() throws InterruptedException {
        Solution q = new Solution(2);
        AtomicBoolean filled = new AtomicBoolean();
        AtomicBoolean thirdPutReturned = new AtomicBoolean();
        AtomicBoolean consumed = new AtomicBoolean();
        AtomicInteger crashes = new AtomicInteger();
        CountDownLatch filledOrDead = new CountDownLatch(1);
        CountDownLatch producerDone = new CountDownLatch(1);
        CountDownLatch consumerDone = new CountDownLatch(1);
        int[] got = new int[3];

        Thread producer = daemon("producer", () -> {
            try {
                q.put(1);
                q.put(2);
                filled.set(true);
                filledOrDead.countDown();
                q.put(3); // capacity is 2: this must block until a take frees a slot
                thirdPutReturned.set(true);
            } catch (Throwable t) {
                crashes.incrementAndGet();
            } finally {
                filledOrDead.countDown();
                producerDone.countDown();
            }
        });

        boolean ok = false;
        if (filledOrDead.await(DEADLINE_MS, TimeUnit.MILLISECONDS) && filled.get()) {
            boolean producerBlocked = awaitParked(producer, thirdPutReturned::get);
            boolean stillBlocked = !thirdPutReturned.get();

            daemon("consumer", () -> {
                try {
                    got[0] = q.take();
                    got[1] = q.take();
                    got[2] = q.take();
                    consumed.set(true);
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                } finally {
                    consumerDone.countDown();
                }
            });

            boolean producerFinished = producerDone.await(DEADLINE_MS, TimeUnit.MILLISECONDS);
            boolean consumerFinished = consumerDone.await(DEADLINE_MS, TimeUnit.MILLISECONDS);
            ok = producerBlocked
                    && stillBlocked
                    && producerFinished
                    && thirdPutReturned.get()
                    && consumerFinished
                    && consumed.get()
                    && got[0] == 1
                    && got[1] == 2
                    && got[2] == 3
                    && crashes.get() == 0;
        }
        Atrophy.check("a put blocked on a full queue completes once a take frees a slot", ok);
    }

    /** Check 3: 2 producers x 1000 items, 2 consumers - every item delivered exactly once. */
    private static void noLossNoDuplication() throws InterruptedException {
        final int PER_PRODUCER = 1000;
        final int TOTAL = 2 * PER_PRODUCER;
        Solution q = new Solution(2);
        AtomicIntegerArray seen = new AtomicIntegerArray(TOTAL + 1);
        AtomicBoolean outOfRange = new AtomicBoolean();
        AtomicInteger crashes = new AtomicInteger();
        CountDownLatch finished = new CountDownLatch(4);

        for (int p = 0; p < 2; p++) {
            final int first = 1 + p * PER_PRODUCER;
            daemon("producer-" + p, () -> {
                try {
                    for (int i = 0; i < PER_PRODUCER; i++) q.put(first + i);
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                } finally {
                    finished.countDown();
                }
            });
        }
        for (int c = 0; c < 2; c++) {
            daemon("consumer-" + c, () -> {
                try {
                    for (int i = 0; i < PER_PRODUCER; i++) {
                        int v = q.take();
                        if (v >= 1 && v <= TOTAL) seen.incrementAndGet(v);
                        else outOfRange.set(true);
                    }
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                } finally {
                    finished.countDown();
                }
            });
        }

        boolean drained = finished.await(15, TimeUnit.SECONDS);
        boolean exact = drained && crashes.get() == 0 && !outOfRange.get();
        if (exact) {
            for (int v = 1; v <= TOTAL; v++) {
                if (seen.get(v) != 1) {
                    exact = false;
                    break;
                }
            }
        }
        Atrophy.check("every item is delivered exactly once across 2 producers and 2 consumers", exact);
    }
}
